import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_src = "torch::Tensor gelu_forward(torch::Tensor x);"

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <c10/cuda/CUDAGuard.h>
#include <cuda_runtime.h>

__device__ __forceinline__ float gelu_tanh_scalar(float v) {
    const float k0 = 0.7978845608028654f;  // sqrt(2 / pi)
    const float k1 = 0.044715f;
    // inner = k0 * v * (1 + k1 * v^2), evaluated with fused multiply-add
    const float v2 = v * v;
    const float poly = __fmaf_rn(k1, v2, 1.0f);
    const float inner = k0 * v * poly;
    const float s = 0.5f * v;
    // 0.5 * v * (1 + tanh(inner)) == s + s * tanh(inner)
    return __fmaf_rn(s, __tanhf(inner), s);
}
__global__ void gelu_tanh_kernel(const float* __restrict__ x,
                                 float* __restrict__ y,
                                 long long n) {
    const long long tid = blockIdx.x * (long long)blockDim.x + threadIdx.x;
    const long long stride = gridDim.x * (long long)blockDim.x;
    const long long n4 = n >> 2;
    const float4* __restrict__ x4 = reinterpret_cast<const float4*>(x);
    float4* __restrict__ y4 = reinterpret_cast<float4*>(y);
    for (long long i = tid; i < n4; i += stride) {
        float4 v = x4[i];
        float4 r;
        r.x = gelu_tanh_scalar(v.x);
        r.y = gelu_tanh_scalar(v.y);
        r.z = gelu_tanh_scalar(v.z);
        r.w = gelu_tanh_scalar(v.w);
        y4[i] = r;
    }
    const long long tail_start = n4 << 2;
    const long long tail_count = n - tail_start;
    if (tid < tail_count) {
        y[tail_start + tid] = gelu_tanh_scalar(x[tail_start + tid]);
    }
}

torch::Tensor gelu_forward(torch::Tensor x) {
    TORCH_CHECK(x.scalar_type() == at::kFloat, "gelu_forward expects float32 input");
    TORCH_CHECK(x.is_cuda(), "gelu_forward expects CUDA tensor");

    at::cuda::CUDAGuard guard(x.device());
    auto xc = x.contiguous();
    auto y = torch::empty_like(xc);
    const long long n = xc.numel();
    if (n == 0) return y;

    const int threads = 256;
    const long long items = (n + 3) >> 2;  // one thread per float4 (plus tail coverage)
    const long long needed = (items + threads - 1) / threads;
    const int blocks = (int)std::min<long long>(needed, 2147483647LL);

    gelu_tanh_kernel<<<blocks, threads, 0, at::cuda::getCurrentCUDAStream()>>>(
        xc.data_ptr<float>(), y.data_ptr<float>(), n);
    C10_CUDA_KERNEL_LAUNCH_CHECK();
    return y;
}
"""

_ext = load_inline(
    name="gelu_tanh_custom_ext",
    cpp_sources=_cpp_src,
    cuda_sources=_cuda_src,
    functions=["gelu_forward"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)

class ModelNew(nn.Module):
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, x):
        if x.is_cuda:
            return _ext.gelu_forward(x)
        if not torch.cuda.is_available():
            raise RuntimeError("ModelNew requires CUDA")
        return _ext.gelu_forward(x.cuda()).cpu()

